from gen import *
V="verb"; N="noun"; A="adjective"; AD="adverb"; P="phrase"
T(75,1,"Обов'язок і заборона: must","Говорити про правила зі словами must і mustn't.",
 "Must + дієслово без to — «треба, обов'язково»: You must wear a seat belt. Mustn't — «заборонено, не можна»: You mustn't smoke here. Don't have to — «не обов'язково» (це інше, ніж mustn't!). Нові слова: rule, law, allowed.",
 [W("must","/mʌst/",V,"треба, мусити","You must stop at a red light.","Треба зупинятися на червоне."),
  W("mustn't","/ˈmʌsnt/",V,"не можна, заборонено","You mustn't smoke here.","Тут не можна курити."),
  W("rule","/ruːl/",N,"правило","This is a school rule.","Це шкільне правило."),
  W("law","/lɔː/",N,"закон","It's the law.","Так велить закон."),
  W("allowed","/əˈlaʊd/",A,"дозволений","Dogs are not allowed here.","Тут не можна з собаками.")],
 ("I'm stressed.","Повторимо. Порадьте відпочити й уникати стресу. Що сказати?",["You should rest and avoid stress.","You should resting and avoid stress.","You rest should avoid stress."],"You should rest and avoid stress."),
 [("You must stop at a red light.","Прослухайте. Що треба?",["Зупинитися на червоне","Їхати далі","Подзвонити"],"Must."),
  ("You mustn't smoke here.","Прослухайте. Що заборонено?",["Курити","Їсти","Спати"],"Mustn't."),
  ("Dogs are not allowed here.","Прослухайте. Що тут не дозволено?",["Собаки","Діти","Кішки"],"Not allowed.")],
 [("You ___ stop at a red light.",["must","mustn't","law"],"Must."),
  ("You ___ smoke here.",["mustn't","must","rule"],"Заборона."),
  ("Dogs are not ___ here.",["allowed","rule","law"],"Allowed.")],
 ("Що значить mustn't?",["не можна","не обов'язково","можна"],"Mustn't — заборонено."),
 ("Тут не можна курити.",["You","mustn't","smoke","here"],["must","law"],"You mustn't smoke here."),
 ("Це шкільне правило.",["This is a school rule"],"This is a school rule."),
 ("Can I smoke here?","Тут заборонено. Що відповісти?",["No, you mustn't.","No, you mustn't to.","No, you not must."],"No, you mustn't."))
T(75,2,"Заборони й дозволи","Говорити про дозволи й заборони.",
 "Forbidden — заборонений, permission — дозвіл, obey — підкорятися, ban — забороняти (також: заборона), penalty — штраф, покарання. Приклад: Smoking is forbidden. Ask for permission. We obey the rules. There is a ban. The penalty is high.",
 [W("forbidden","/fəˈbɪdn/",A,"заборонений","Smoking is forbidden.","Палити заборонено."),
  W("permission","/pəˈmɪʃn/",N,"дозвіл","Ask for permission.","Попросіть дозволу."),
  W("obey","/əˈbeɪ/",V,"підкорятися","We obey the rules.","Ми дотримуємося правил."),
  W("ban","/bæn/",N,"заборона","There is a ban on cars.","Є заборона на авто."),
  W("penalty","/ˈpenlti/",N,"штраф, покарання","The penalty is high.","Штраф високий.")],
 ("Can I smoke here?","Повторимо. Тут заборонено. Що відповісти?",["No, you mustn't.","No, you mustn't to.","No, you not must."],"No, you mustn't."),
 [("Smoking is forbidden.","Прослухайте. Що заборонено?",["Палити","Говорити","Їсти"],"Forbidden."),
  ("Ask for permission.","Прослухайте. Що треба?",["Попросити дозвіл","Піти","Заплатити"],"Permission."),
  ("The penalty is high.","Прослухайте. Який штраф?",["Високий","Низький","Нульовий"],"High.")],
 [("Smoking is ___.",["forbidden","permission","ban"],"Заборонено."),
  ("Ask for ___.",["permission","penalty","obey"],"Дозвіл."),
  ("We ___ the rules.",["obey","ban","forbidden"],"Obey.")],
 ("Що таке penalty?",["штраф","дозвіл","заборона"],"Penalty — штраф, покарання."),
 ("Ми дотримуємося правил.",["We","obey","the","rules"],["obeys","ban"],"We obey the rules."),
 ("Попросіть дозволу.",["Ask for permission"],"Ask for permission."),
 ("What happens if I break the rule?","Заплатите штраф. Що відповісти?",["You pay a penalty.","You paying penalty.","You are pay a penalty."],"You pay a penalty."))
